import{_ as t,a as o,o as a,a6 as r}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse(`{"title":"Get Compare Items","description":"","frontmatter":{"outline":false,"examples":[{"id":"list-compare-items","title":"Get Compare Items","description":"Retrieve the authenticated customer's product comparison list.","request":"GET /api/shop/compare_items\\nAccept: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer 12|Iy8NExampleCustomerAccessToken\\n","response":"HTTP/1.1 200 OK\\nX-Total-Count: 2\\nX-Page: 1\\nX-Per-Page: 30\\nX-Total-Pages: 1\\n\\n[\\n  {\\n    \\"id\\": 155,\\n    \\"createdAt\\": \\"2026-08-07T15:56:42+05:30\\",\\n    \\"updatedAt\\": \\"2026-08-07T15:56:42+05:30\\",\\n    \\"product\\": \\"/api/shop/products/126\\",\\n    \\"customer\\": \\"/api/shop/customers/122\\"\\n  },\\n  {\\n    \\"id\\": 156,\\n    \\"createdAt\\": \\"2026-08-07T15:57:10+05:30\\",\\n    \\"updatedAt\\": \\"2026-08-07T15:57:10+05:30\\",\\n    \\"product\\": \\"/api/shop/products/127\\",\\n    \\"customer\\": \\"/api/shop/customers/122\\"\\n  }\\n]\\n","commonErrors":[{"error":"403 Forbidden","cause":"No customer Bearer token was sent","solution":"Log the customer in; guests hold no comparison list"},{"error":"Empty array","cause":"The customer has added nothing to compare","solution":"This is a normal empty state, not an error"}]}]},"headers":[],"relativePath":"api/rest-api/shop/compare/list.md","filePath":"api/rest-api/shop/compare/list.md","lastUpdated":1786429091000}`),s={name:"api/rest-api/shop/compare/list.md"};function d(i,e,n,c,p,h){return a(),o("div",null,e[0]||(e[0]=[r('<h1 id="get-compare-items" tabindex="-1">Get Compare Items <a class="header-anchor" href="#get-compare-items" aria-label="Permalink to &quot;Get Compare Items&quot;">​</a></h1><p>Retrieve the products in the authenticated customer&#39;s comparison list.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/shop/compare_items</span></span></code></pre></div><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>Customer Bearer token (<code>Bearer &lt;accessToken&gt;</code>)</td></tr></tbody></table><h2 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h2><p>A bare JSON array of comparison rows. Each row identifies its product and customer by <strong>path reference, not as a nested object</strong> — the product&#39;s name, price, and attributes are not in this payload.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Comparison row ID. Use it on <a href="/api/rest-api/shop/compare/get.html">Get One</a> and <a href="/api/rest-api/shop/compare/delete.html">Delete</a>.</td></tr><tr><td><code>product</code></td><td>string</td><td>Path of the compared product, e.g. <code>/api/shop/products/126</code>. The trailing segment is the product ID.</td></tr><tr><td><code>customer</code></td><td>string</td><td>Path of the owning customer.</td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td>string</td><td>ISO 8601 timestamps.</td></tr></tbody></table><p>Pagination is reported in headers, not in the body: <code>X-Total-Count</code>, <code>X-Page</code>, <code>X-Per-Page</code>, <code>X-Total-Pages</code>.</p><p>Unlike the wishlist, the comparison list is <strong>not scoped to a channel</strong> — the same rows come back on every channel.</p><p>Over GraphQL the same rows expose <code>product</code> and <code>customer</code> as nested objects selectable in one query — see <a href="/api/graphql-api/shop/queries/get-compare-items.html">Get Compare Items</a>.</p><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>Comparison table</strong> — read the rows, take the numeric ID from the end of each <code>product</code> path, and fetch those products with their attribute values to build the table columns.</li><li><strong>&quot;Compare (n)&quot; badge</strong> — read <code>X-Total-Count</code>; the array holds only the current page.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Do not expect product attributes here</strong> — the row is a pointer, so a comparison view always needs a second round of product fetches, or the GraphQL query instead.</li><li><strong>Fetch the products in one call</strong> — the product listing endpoint accepts filters, so a single request can return every compared product rather than one request per row.</li><li><strong>Keep the row <code>id</code> alongside the product ID</strong> — deletion addresses the comparison row, not the product.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/compare/get.html">Get Single Compare Item</a> — one comparison row by id</li><li><a href="/api/rest-api/shop/compare/create.html">Create Compare Item</a> — add a product to the comparison list</li><li><a href="/api/rest-api/shop/compare/delete.html">Delete Compare Item</a> — remove one comparison row</li><li><a href="/api/rest-api/shop/compare/delete-all.html">Delete All Compare Items</a> — clear the whole comparison list</li></ul>',18)]))}const u=t(s,[["render",d]]);export{m as __pageData,u as default};
